/** Serializable application contracts shared by renderer and native code. No runtime or framework imports. */
export type TaskRun = { id: string; chatId: string; status: 'queued' | 'running' | 'completed' | 'failed' | 'cancelled' | 'interrupted' | 'blocked' | 'unverified'; startedAt: string; finishedAt?: string; error?: string };
export type ScheduledTask = {
  id: string; name: string; prompt: string; projectPath: string; provider: string; model: string;
  interval: string; every: string; time: string; timeZone: string; weekday: number;
  status: 'active' | 'paused'; notifications: string; reasoning: string;
  language?: 'es' | 'en';
  autonomous?: boolean;
  allowComputer?: boolean;
  maximumAutonomy?: boolean;
  requiresAdministrator?: boolean;
  proactive?: boolean;
  deliveryChatId?: string;
  orbId?: string;
  nextRun?: string; lastRun?: string; runs: TaskRun[];
  runAt?: string;
};

export type SessionChat = { chatId: string; projectPath: string; name?: string; projectName?: string };
export type SessionView = SessionChat & { key: string; runId: string; state: string; tool: string; busy: boolean; startedAt: number; updatedAt: number; messages: any[]; approvals: any[]; localOwner?: boolean; external?: boolean; url?: string };
export type ChatPage = { messages: any[]; total: number; start: number; before?: number; hasMore?: boolean };
/** Keep this surface aligned with preload.cjs. Dynamic invoke remains extensible for tools/plugins. */
export interface DesktopBridge {
  invoke: <T = unknown>(command: string, args?: Record<string, unknown>) => Promise<T>;
  onTerminalOutput: (handler: (payload: any) => void) => (() => void);
  settingsGet: (key: string) => Promise<any>;
  settingsSet: (key: string, value: unknown) => Promise<void>;
  settingsRemove: (key: string) => Promise<void>;
  globalChatUpsert: (...args: any[]) => Promise<any>;
  onSettingsChanged: (handler: (payload: any) => void) => (() => void);
  listProjects: (...args: any[]) => Promise<any>;
  selectProjectFolder: (...args: any[]) => Promise<any>;
  selectFiles: (...args: any[]) => Promise<any>;
  readFile: (path: string) => Promise<number[]>;
  readTextFile: (path: string) => Promise<string>;
  fileExists: (path: string) => Promise<boolean>;
  makeDirectory: (path: string) => Promise<boolean>;
  writeTextFile: (path: string, content: string) => Promise<boolean>;
  appendLog: (...args: any[]) => Promise<any>;
  removeFile: (path: string) => Promise<boolean>;
  joinPath: (...parts: string[]) => Promise<string>;
  appConfigDir: () => Promise<string>;
  appCacheDir: () => Promise<string>;
  readProjectChat: (...args: any[]) => Promise<any>;
  chatPage: (project: string, id: string, before?: number, limit?: number) => Promise<ChatPage>;
  chatTurns: (...args: any[]) => Promise<any>;
  chatContext: (project: string, id: string) => Promise<{ messages: any[]; summary: string }>;
  chatSaveTail: (...args: any[]) => Promise<any>;
  chatAppend: (project: string, id: string, message: any) => Promise<number>;
  chatAll: (project: string, id: string) => Promise<any[]>;
  chatSearch: (project: string, id: string, query: string) => Promise<string[]>;
  chatCopy: (...args: any[]) => Promise<any>;
  chatDelete: (...args: any[]) => Promise<any>;
  chatTranscript: (...args: any[]) => Promise<any>;
  writeProjectChat: (...args: any[]) => Promise<any>;
  switchProject: (...args: any[]) => Promise<any>;
  renameProject: (...args: any[]) => Promise<any>;
  windowMinimize: (...args: any[]) => Promise<any>;
  windowMaximize: (...args: any[]) => Promise<any>;
  windowClose: (...args: any[]) => Promise<any>;
  windowIsFullScreen: (...args: any[]) => Promise<any>;
  onFullscreenChange: (handler: (payload: any) => void) => (() => void);
  floatingResize: (...args: any[]) => Promise<any>;
  floatingClose: (...args: any[]) => Promise<any>;
  floatingHidden: (...args: any[]) => Promise<any>;
  onFloatingHide: (handler: (payload: any) => void) => (() => void);
  floatingPointer: (...args: any[]) => Promise<any>;
  sessionList: () => Promise<SessionView[]>;
  tasksList: (projectPath?: string) => Promise<ScheduledTask[]>;
  tasksSave: (projectPath: string, task: Partial<ScheduledTask>) => Promise<ScheduledTask>;
  tasksDelete: (projectPath: string, id: string) => Promise<unknown>;
  tasksRun: (projectPath: string, id: string) => Promise<TaskRun>;
  tasksCancel: (projectPath: string, id: string) => Promise<unknown>;
  taskAssignment: () => Promise<{ task: ScheduledTask; run: TaskRun } | null>;
  taskFinish: (error?: string) => Promise<void>;
  onTasksChanged: (handler: (payload: any) => void) => (() => void);
  broadcastOrbPalette: (index: number) => void;
  onOrbPaletteChange: (handler: (payload: any) => void) => (() => void);
  getPathForFile: (file: File) => string;
  integrationConfig: (...args: any[]) => Promise<any>;
  integrationSave: (...args: any[]) => Promise<any>;
  hooksPreview: (...args: any[]) => Promise<any>;
  hooksInstall: (...args: any[]) => Promise<any>;
  credentialPresent: (key: string) => Promise<boolean>;
  credentialSet: (...args: any[]) => Promise<any>;
  openExternal: (...args: any[]) => Promise<any>;
  sessionSelect: (...args: any[]) => Promise<any>;
  mobileNext: (...args: any[]) => Promise<any>;
  mobileTake: (...args: any[]) => Promise<any>;
  mobileRelease: (...args: any[]) => Promise<any>;
  sessionSelected: () => Promise<SessionChat | null>;
  sessionClaim: (chat: SessionChat) => Promise<string>;
  sessionPublish: (chat: SessionChat, runId: string, snapshot: Record<string, unknown>) => Promise<unknown>;
  sessionCommand: (...args: any[]) => Promise<any>;
  sessionOpen: (...args: any[]) => Promise<any>;
  onSessions: (handler: (payload: any) => void) => (() => void);
  onSessionCommand: (handler: (payload: any) => void) => (() => void);
  onSessionOpen: (handler: (payload: any) => void) => (() => void);
  floatingDrag: (...args: any[]) => Promise<any>;
  floatingOpenMain: (...args: any[]) => Promise<any>;
  onMainShow: (handler: (payload: any) => void) => (() => void);
  onFloatingShow: (handler: (payload: any) => void) => (() => void);
  reloadApp: (...args: any[]) => Promise<any>;
  getAutoUpdateStatus: (...args: any[]) => Promise<any>;
  checkForUpdates: (...args: any[]) => Promise<any>;
  installUpdate: (...args: any[]) => Promise<any>;
  onAutoUpdate: (handler: (payload: any) => void) => (() => void);
  setComputerOverlay: (...args: any[]) => Promise<any>;
  onComputerEscape: (handler: (payload: any) => void) => (() => void);
  computerMenuAction: (action: string) => void;
  onComputerContext: (handler: (payload: any) => void) => (() => void);
}
